// Team marks for the daily-goal email.
//
// The artwork is baked in as base64 rather than read from public/ at runtime.
// A serverless function has no guarantee the static folder was traced into its
// bundle, and a logo that 404s leaves a hole in the header band — so the bytes
// travel with the code. Each one is a 124px PNG (2x the 62px the band draws it
// at), quantised to 128 colours: at this size that is invisible and costs a
// third of the file.
//
// The same bytes serve both paths: a browser preview takes the data: URI, and
// a real send takes the raw base64 and attaches it under cid:team-SLUG,
// because Gmail strips data: URLs out of mail it delivers.

export type TeamLogo = { team: string; slug: string; b64: string };

export const TEAM_LOGOS: TeamLogo[] = [
  { team: "Cash Flow Commanders", slug: "cash-flow-commanders", b64: "" },
  { team: "Cash Flow Cowboys", slug: "cash-flow-cowboys", b64: "" },
  { team: "CTC Crusaders", slug: "ctc-crusaders", b64: "" },
  { team: "Lien Kings", slug: "lien-kings", b64: "" },
  { team: "Bone Crushers", slug: "bone-crushers", b64: "" },
];

export const teamLogoCid = (slug: string) => `team-${slug}`;

/** { team name -> src } for renderDigest's photos.logos. `mode` picks the
 *  reference style: "data" for anything rendered in a browser, "cid" for a
 *  message whose parts the mailer will attach. */
export function teamLogoSrcs(mode: "data" | "cid"): Record<string, string> {
  const out: Record<string, string> = {};
  for (const l of TEAM_LOGOS) {
    out[l.team] = mode === "data"
      ? `data:image/png;base64,${l.b64}`
      : `cid:${teamLogoCid(l.slug)}`;
  }
  return out;
}
